<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Hash,Storage};
use Illuminate\Http\UploadedFile;
use App\Models\User;
use App\Services\{Reminders,Letters};
class ApplicationTest extends TestCase {
 use RefreshDatabase;
 private User $admin;private User $rt;private User $rw;private User $citizen;private User $outsider;private int $rtId;private int $otherRt;private int $warga;private int $child;private int $otherWarga;private int $kk;private int $house;
 protected function setUp():void {parent::setUp();config(['hashing.bcrypt.rounds'=>4]);Storage::fake('local');$this->seed();$a=['created_at'=>now(),'updated_at'=>now()];$rw=DB::table('rw')->insertGetId(['kode'=>'03','nama'=>'Lingkungan Melati','kelurahan'=>'Setu']+$a);$rw2=DB::table('rw')->insertGetId(['kode'=>'04','nama'=>'Lingkungan Mawar','kelurahan'=>'Setu']+$a);$this->rtId=DB::table('rt')->insertGetId(['rw_id'=>$rw,'nomor'=>'003']+$a);$this->otherRt=DB::table('rt')->insertGetId(['rw_id'=>$rw2,'nomor'=>'004']+$a);$this->house=DB::table('hunian')->insertGetId(['rt_id'=>$this->rtId,'alamat'=>'Jl. Melati 12','jenis'=>'rumah']+$a);$h2=DB::table('hunian')->insertGetId(['rt_id'=>$this->otherRt,'alamat'=>'Alamat RAHASIA luar wilayah','jenis'=>'rumah']+$a);$this->kk=DB::table('kartu_keluarga')->insertGetId(['hunian_id'=>$this->house,'nomor_kk'=>'3174000000000001','status'=>'aktif']+$a);$k2=DB::table('kartu_keluarga')->insertGetId(['hunian_id'=>$h2,'nomor_kk'=>'3174000000000002','status'=>'aktif']+$a);
  $this->warga=DB::table('warga')->insertGetId(['kartu_keluarga_id'=>$this->kk,'nama'=>'Andi Pratama','nik'=>'3174000000000011','jenis_kelamin'=>'L','hubungan_keluarga'=>'kepala_keluarga','status'=>'aktif']+$a);$this->child=DB::table('warga')->insertGetId(['kartu_keluarga_id'=>$this->kk,'nama'=>'Anak Andi','nik'=>null,'jenis_kelamin'=>'P','hubungan_keluarga'=>'anak','status'=>'aktif']+$a);$this->otherWarga=DB::table('warga')->insertGetId(['kartu_keluarga_id'=>$k2,'nama'=>'Warga RAHASIA','nik'=>'3174000000000022','jenis_kelamin'=>'P','hubungan_keluarga'=>'kepala_keluarga','status'=>'aktif']+$a);
  $this->admin=$this->user('ADMINISTRATOR');$this->rt=$this->user('RT',['rt_id'=>$this->rtId,'jabatan'=>'Ketua RT']);$this->rw=$this->user('RW',['rw_id'=>$rw,'jabatan'=>'Ketua RW']);$this->citizen=$this->user('WARGA',['warga_id'=>$this->warga]);$this->outsider=$this->user('WARGA',['warga_id'=>$this->otherWarga]);
 }
 private function user(string $role,array $extra=[]):User{return User::create(['peran_id'=>DB::table('peran')->where('kode',$role)->value('id'),'nama'=>'Pengguna '.$role,'email'=>strtolower($role).'-'.bin2hex(random_bytes(4)).'@contoh.test','password_hash'=>Hash::make('TestPassword-1234'),'aktif'=>true]+$extra);}
 private function letter(?User $who=null,?int $person=null):int{$who??=$this->citizen;$person??=$this->warga;$this->actingAs($who)->post('/surat/baru',['warga_id'=>$person,'jenis_surat_id'=>DB::table('jenis_surat')->where('kode','DOMISILI')->value('id'),'keperluan'=>'Administrasi pekerjaan'])->assertRedirect('/surat');return DB::table('permohonan_surat')->max('id');}
 private function issue():int{$id=$this->letter();$this->actingAs($this->rt)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertRedirect();$this->actingAs($this->rw)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertRedirect();return $id;}
 public function test_guest_must_login():void{$this->get('/')->assertRedirect('/masuk');}
 public function test_login_uses_real_password_and_logout():void{$this->post('/masuk',['email'=>$this->admin->email,'password'=>'salah'])->assertSessionHasErrors();$this->post('/masuk',['email'=>$this->admin->email,'password'=>'TestPassword-1234'])->assertRedirect('/');$this->assertAuthenticatedAs($this->admin);$this->post('/keluar')->assertRedirect('/masuk');$this->assertGuest();}
 public function test_all_password_updates_accept_six_characters_and_reject_five():void{$role=DB::table('peran')->where('kode','RT')->value('id');$payload=['nama'=>'Operator Baru','email'=>'operator-six@contoh.test','peran_id'=>$role,'rt_id'=>$this->rtId,'jabatan'=>'Perangkat RT','aktif'=>1];$this->actingAs($this->admin)->post('/data/pengguna/baru',$payload+['password'=>'Abc12'])->assertSessionHasErrors('password');$this->post('/data/pengguna/baru',$payload+['password'=>'Abc123'])->assertRedirect('/data/pengguna');$created=User::where('email','operator-six@contoh.test')->firstOrFail();$this->assertTrue(Hash::check('Abc123',$created->password_hash));$this->post('/profil/password',['current_password'=>'TestPassword-1234','password'=>'Abc12','password_confirmation'=>'Abc12'])->assertSessionHasErrors('password');$this->post('/profil/password',['current_password'=>'TestPassword-1234','password'=>'Abc123','password_confirmation'=>'Abc123'])->assertRedirect();$this->admin->refresh();$this->assertTrue(Hash::check('Abc123',$this->admin->password_hash));}
 public function test_admin_pages_and_forms_render():void{$this->actingAs($this->admin);foreach(['/','/data/warga','/data/keluarga','/data/hunian','/data/pengguna','/data/menu','/data/rw','/data/rt','/mutasi','/mutasi/baru','/tamu','/tamu/baru','/sewa','/sewa/baru','/surat','/surat/baru','/arsip','/laporan','/notifikasi','/profil','/log','/backup','/data/warga/baru','/data/pengguna/baru','/data/menu/baru'] as $path)$this->get($path)->assertOk();$this->get('/data/pengguna/baru')->assertSee('Kata sandi (minimal 6 karakter)')->assertSee('minlength="6"',false);$this->get('/profil')->assertSee('Kata sandi baru (minimal 6 karakter)');}
 public function test_citizen_cannot_manage_users_or_other_residents():void{$this->actingAs($this->citizen)->get('/data/pengguna')->assertForbidden();$this->get('/data/warga')->assertForbidden();$this->post('/data/pengguna/baru',[])->assertForbidden();}
 public function test_rt_cannot_read_other_region():void{$this->actingAs($this->rt)->get('/data/warga')->assertOk()->assertSee('Andi Pratama')->assertDontSee('Warga RAHASIA');$this->get('/data/warga/'.$this->otherWarga.'/ubah')->assertNotFound();}
 public function test_rw_cannot_read_other_rw():void{$this->actingAs($this->rw)->get('/data/warga')->assertDontSee('Warga RAHASIA');$this->get('/laporan?rt='.$this->otherRt)->assertForbidden();}
 public function test_citizen_cannot_submit_for_other_person():void{$this->actingAs($this->citizen)->post('/surat/baru',['warga_id'=>$this->otherWarga,'jenis_surat_id'=>DB::table('jenis_surat')->first()->id,'keperluan'=>'Uji akses'])->assertForbidden();}
 public function test_other_citizen_cannot_read_request():void{$id=$this->letter();$this->actingAs($this->outsider)->get('/surat/'.$id)->assertNotFound();}
 public function test_secretary_cannot_approve():void{$id=$this->letter();$this->actingAs($this->rt)->post('/surat/'.$id.'/persetujuan',['status'=>'approved']);$secretary=$this->user('RW',['rw_id'=>$this->rw->rw_id,'jabatan'=>'Sekretaris RW']);$this->actingAs($secretary)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertForbidden();}
 public function test_superuser_does_not_impersonate_approval():void{$id=$this->letter();$this->actingAs($this->admin)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertForbidden();}
 public function test_rw_cannot_skip_rt():void{$id=$this->letter();$this->actingAs($this->rw)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertStatus(422);$this->assertDatabaseCount('surat_terbit',0);}
 public function test_pending_retains_stage_with_note():void{$id=$this->letter();$this->actingAs($this->rt)->post('/surat/'.$id.'/persetujuan',['status'=>'pending','catatan'=>'Lengkapi keterangan'])->assertRedirect();$this->assertDatabaseHas('permohonan_surat',['id'=>$id,'status'=>'pending_rt','catatan_rt'=>'Lengkapi keterangan']);}
 public function test_rt_rw_workflow_creates_real_pdf_and_token():void{$id=$this->issue();$s=DB::table('surat_terbit')->where('permohonan_id',$id)->first();$this->assertNotNull($s);$f=DB::table('berkas')->find($s->berkas_id);$this->assertStringStartsWith('%PDF-',Storage::disk('local')->get($f->path));$snapshot=json_decode($s->snapshot,true);$token=basename($snapshot['verifikasi']);$this->assertSame(hash('sha256',$token),$s->token_qr_hash);$this->actingAs($this->citizen)->get('/berkas/'.$f->id)->assertOk();$this->get('/verifikasi/'.$token)->assertOk()->assertSee('Surat tercatat')->assertDontSee('3174000000000011');}
 public function test_duplicate_approval_cannot_generate_duplicate_number():void{$id=$this->issue();$this->actingAs($this->rw)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertStatus(422);$this->assertDatabaseCount('surat_terbit',1);$this->assertEquals(1,DB::table('penomoran_surat')->value('nomor_terakhir'));}
 public function test_second_letter_gets_next_number():void{$this->issue();$this->issue();$this->assertEquals([1,2],DB::table('surat_terbit')->orderBy('id')->pluck('nomor_urut')->all());}
 public function test_request_revision_restarts_approval():void{$id=$this->letter();$this->actingAs($this->rt)->post('/surat/'.$id.'/persetujuan',['status'=>'approved']);$this->actingAs($this->admin)->post('/surat/'.$id.'/ubah',['warga_id'=>$this->warga,'jenis_surat_id'=>DB::table('jenis_surat')->where('kode','DOMISILI')->value('id'),'keperluan'=>'Keperluan baru'])->assertRedirect();$this->assertDatabaseHas('permohonan_surat',['id'=>$id,'status'=>'pending_rt','revisi'=>2]);$this->assertDatabaseCount('persetujuan_surat',1);$this->actingAs($this->rw)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertStatus(422);}
 public function test_revoke_changes_public_verification():void{$id=$this->issue();$s=DB::table('surat_terbit')->first();$token=basename(json_decode($s->snapshot,true)['verifikasi']);$this->actingAs($this->admin)->post('/surat/'.$id.'/cabut')->assertRedirect();$this->get('/verifikasi/'.$token)->assertOk()->assertSee('Surat tidak berlaku');}
 public function test_private_file_denies_other_citizen():void{$this->issue();$f=DB::table('surat_terbit')->value('berkas_id');$this->actingAs($this->outsider)->get('/berkas/'.$f)->assertForbidden();}
 public function test_guest_requires_identity_and_valid_range():void{$this->actingAs($this->citizen)->post('/tamu/baru',['nama'=>'Tamu','hunian_id'=>$this->house,'alamat_asal'=>'Jakarta','tujuan'=>'Keluarga','mulai'=>'2026-10-15T12:00','rencana_selesai'=>'2026-10-16T12:00'])->assertStatus(422);$this->postJson('/tamu/baru',['nama'=>'Tamu','nik'=>'3174000000000099','hunian_id'=>$this->house,'alamat_asal'=>'Jakarta','tujuan'=>'Keluarga','mulai'=>'2026-10-16T12:00','rencana_selesai'=>'2026-10-15T12:00'])->assertUnprocessable();}
 public function test_guest_create_update_and_finish():void{$this->actingAs($this->citizen)->post('/tamu/baru',['nama'=>'Tamu Contoh','nik'=>'3174000000000099','hunian_id'=>$this->house,'alamat_asal'=>'Jakarta','tujuan'=>'Keluarga','mulai'=>now()->subDays(2)->format('Y-m-d H:i'),'rencana_selesai'=>now()->subDay()->format('Y-m-d H:i')])->assertRedirect('/tamu');$id=DB::table('tamu_menginap')->value('id');$this->get('/tamu/'.$id.'/ubah')->assertOk();$this->post('/tamu/'.$id.'/selesai')->assertRedirect();$this->assertNotNull(DB::table('tamu_menginap')->value('selesai_aktual'));}
 public function test_reminders_deduplicate_per_recipient():void{DB::table('tamu_menginap')->insert(['hunian_id'=>$this->house,'pelapor_id'=>$this->citizen->id,'nama'=>'Tamu lewat','nik'=>'3174000000000088','alamat_asal'=>'Jakarta','tujuan'=>'Keluarga','mulai'=>now()->subDays(3),'rencana_selesai'=>now()->subDay(),'created_at'=>now(),'updated_at'=>now()]);$first=Reminders::run();$this->assertGreaterThan(0,$first);$this->assertSame(0,Reminders::run());$this->assertFalse(DB::table('notifikasi')->where('penerima_id',$this->outsider->id)->exists());}
 public function test_birth_is_applied_once_and_allows_null_nik():void{$this->actingAs($this->citizen)->post('/mutasi/baru',['jenis'=>'lahir','tanggal_peristiwa'=>today()->toDateString(),'kk_tujuan_id'=>$this->kk,'nama'=>'Bayi Baru','jenis_kelamin'=>'L','hubungan_keluarga'=>'anak','nama_ayah'=>'Andi','nama_ibu'=>'Maya','surat_lahir'=>UploadedFile::fake()->create('surat.pdf',10,'application/pdf')])->assertRedirect('/mutasi');$mid=DB::table('mutasi')->value('id');$this->assertDatabaseHas('warga',['nama'=>'Bayi Baru','nik'=>null,'status'=>'draf']);$this->actingAs($this->rt)->get('/mutasi/'.$mid)->assertOk();$this->post('/mutasi/'.$mid.'/terapkan')->assertRedirect();$this->assertDatabaseHas('warga',['nama'=>'Bayi Baru','status'=>'aktif']);$this->post('/mutasi/'.$mid.'/terapkan')->assertStatus(422);$this->assertDatabaseCount('mutasi_lahir',1);}
 public function test_departing_family_head_requires_replacement():void{$this->actingAs($this->citizen)->post('/mutasi/baru',['jenis'=>'keluar','tanggal_peristiwa'=>today()->toDateString(),'warga_id'=>$this->warga,'alamat_tujuan'=>'Bandung','alasan'=>'Pekerjaan'])->assertRedirect();$id=DB::table('mutasi')->value('id');$this->actingAs($this->rt)->post('/mutasi/'.$id.'/terapkan')->assertStatus(422);$this->post('/mutasi/'.$id.'/terapkan',['pengganti_id'=>$this->child])->assertRedirect();$this->assertDatabaseHas('warga',['id'=>$this->warga,'status'=>'pindah']);$this->assertDatabaseHas('warga',['id'=>$this->child,'hubungan_keluarga'=>'kepala_keluarga']);}
 public function test_spreadsheet_and_report_pdf_are_generated():void{$this->letter();$this->actingAs($this->rw)->get('/laporan/ekspor/pdf?bulan='.now()->format('Y-m'))->assertOk()->assertHeader('Content-Type','application/pdf');$response=$this->get('/laporan/ekspor/xlsx?bulan='.now()->format('Y-m'));$response->assertOk();$file=$response->baseResponse->getFile()->getPathname();$this->assertSame('PK',file_get_contents($file,false,null,0,2));}
 public function test_admin_cannot_delete_own_account():void{$this->actingAs($this->admin)->post('/data/pengguna/'.$this->admin->id.'/hapus')->assertStatus(422);}
 public function test_admin_create_user_and_edit_menu():void{$role=DB::table('peran')->where('kode','RT')->value('id');$this->actingAs($this->admin)->post('/data/pengguna/baru',['nama'=>'Operator Baru','email'=>'operator@contoh.test','password'=>'PasswordBaru-1234','peran_id'=>$role,'rt_id'=>$this->rtId,'jabatan'=>'Perangkat RT','aktif'=>1])->assertRedirect();$u=User::where('email','operator@contoh.test')->first();$this->assertTrue(Hash::check('PasswordBaru-1234',$u->password_hash));$this->get('/data/pengguna/'.$u->id.'/ubah')->assertOk();}
 public function test_direct_module_access_respects_menu_permission():void{$menu=DB::table('menu')->where('kode','surat')->value('id');DB::table('hak_akses_menu')->where('peran_id',$this->citizen->peran_id)->where('menu_id',$menu)->update(['lihat'=>false]);$this->actingAs($this->citizen)->get('/surat')->assertForbidden();}
 public function test_head_can_be_changed_atomically():void{$this->actingAs($this->rt)->post('/data/keluarga/'.$this->kk.'/kepala',['kepala_id'=>$this->child])->assertRedirect();$this->assertDatabaseHas('warga',['id'=>$this->child,'hubungan_keluarga'=>'kepala_keluarga']);$this->assertDatabaseHas('warga',['id'=>$this->warga,'hubungan_keluarga'=>'lainnya']);}
 public function test_move_in_creates_active_head_of_new_family():void{$kk=DB::table('kartu_keluarga')->insertGetId(['hunian_id'=>$this->house,'nomor_kk'=>'3174000000000099','status'=>'aktif','created_at'=>now(),'updated_at'=>now()]);$this->actingAs($this->rt)->post('/mutasi/baru',['jenis'=>'masuk','tanggal_peristiwa'=>today()->toDateString(),'kk_tujuan_id'=>$kk,'nama'=>'Pendatang Baru','nik'=>'3174000000000099','tanggal_lahir'=>'1990-01-01','jenis_kelamin'=>'L','hubungan_keluarga'=>'kepala_keluarga','telepon'=>'08123456789','alamat_asal'=>'Bandung','status_rumah'=>'kontrak','ktp'=>UploadedFile::fake()->create('ktp.pdf',10,'application/pdf'),'kkfile'=>UploadedFile::fake()->create('kk.pdf',10,'application/pdf')])->assertRedirect();$id=DB::table('mutasi')->max('id');$this->post('/mutasi/'.$id.'/terapkan')->assertRedirect();$this->assertDatabaseHas('warga',['nama'=>'Pendatang Baru','status'=>'aktif','kartu_keluarga_id'=>$kk]);}
 public function test_death_updates_resident_status():void{$this->actingAs($this->rt)->post('/mutasi/baru',['jenis'=>'mati','tanggal_peristiwa'=>today()->toDateString(),'warga_id'=>$this->child,'penyebab'=>'sakit','surat_mati'=>UploadedFile::fake()->create('kematian.pdf',10,'application/pdf')])->assertRedirect();$id=DB::table('mutasi')->max('id');$this->post('/mutasi/'.$id.'/terapkan')->assertRedirect();$this->assertDatabaseHas('warga',['id'=>$this->child,'status'=>'meninggal']);}
 public function test_sewa_has_emergency_contact_and_end_date():void{$this->actingAs($this->citizen)->post('/sewa/baru',['hunian_id'=>$this->house,'nama'=>'Penghuni Kos','nik'=>'3174000000000077','tanggal_masuk'=>today()->toDateString(),'tanggal_selesai'=>today()->addMonths(3)->toDateString(),'nama_kontak_darurat'=>'Keluarga','telepon_darurat'=>'08123456789'])->assertRedirect('/sewa');$id=DB::table('sewa_penghuni')->value('id');$this->get('/sewa/'.$id.'/ubah')->assertOk();$this->post('/sewa/'.$id.'/selesai')->assertRedirect();}
 public function test_all_five_letter_types_can_be_issued():void{foreach(DB::table('jenis_surat')->get() as $j){$data=['warga_id'=>$this->warga,'jenis_surat_id'=>$j->id,'keperluan'=>'Pengujian surat '.$j->nama,'isian'=>['nama_usaha'=>'Warung Contoh','jenis_usaha'=>'Kuliner','alamat_usaha'=>'Jl Melati','nama_calon'=>'Calon Pasangan','nik_calon'=>'3174000000000090','pengurusan'=>'KTP baru','tujuan_bantuan'=>'Biaya pendidikan']];$this->actingAs($this->citizen)->post('/surat/baru',$data)->assertRedirect();$id=DB::table('permohonan_surat')->max('id');$this->actingAs($this->rt)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertRedirect();$this->actingAs($this->rw)->post('/surat/'.$id.'/persetujuan',['status'=>'approved'])->assertRedirect();}$this->assertDatabaseCount('surat_terbit',5);}

}
